if (user.role === ROLES.INTERN) {
  const selfInternId = await this.repository.findInternIdByUserId(user.id);
  if (!selfInternId) throw new AppError('Intern profile not found', 404, ERROR_CODE.NOT_FOUND);
  targetInternId = selfInternId;
} else if (user.role === ROLES.ADMIN) {
  if (!requestedInternId) throw new AppError('internId query parameter is required', 400, ERROR_CODE.VALIDATION_ERROR);
  targetInternId = requestedInternId;
} else if (user.role === ROLES.LEADER) {
  if (!requestedInternId) throw new AppError('internId query parameter is required', 400, ERROR_CODE.VALIDATION_ERROR);
  const hasAccess = await this.repository.checkLeaderAccessToIntern(user.id, requestedInternId);
  if (!hasAccess) throw new AppError('Forbidden: You do not manage this intern', 403, ERROR_CODE.FORBIDDEN);
  targetInternId = requestedInternId;
} else {
  throw new AppError('Forbidden', 403, ERROR_CODE.FORBIDDEN);
}

if (actor.role === ROLES.INTERN) {
  const intern = await prisma.intern.findUnique({ where: { userId: actor.id } });
  const isOwner = intern && submission.assignment.internId === intern.id;
  const isSupport = intern && submission.assignment.supportId === intern.id;
  if (!isOwner && !isSupport) {
    throw new AppError('Forbidden: You can only add attachments to your own submissions', 403, ERROR_CODE.FORBIDDEN);
  }
}

export const updateMeInternSchema = z.object({
  phone: z.string().regex(VIETNAMESE_PHONE_REGEX, 'Số điện thoại không đúng định dạng Việt Nam').optional(),
  discordUsername: z.string().nullable().optional(),
  university: z.string().trim().nullable().optional(),
  major: z.string().trim().nullable().optional(),
});

if (actor.role !== ROLES.ADMIN) {
  const isParticipant = meeting.participants?.some((p: any) => p.userId === actor.id);
  const isHost = meeting.hostId === actor.id || meeting.createdBy === actor.id;
  if (!isParticipant && !isHost && meeting.visibility === 'PRIVATE') {
    throw new AppError('Forbidden: You do not have access to this meeting', 403, ERROR_CODE.FORBIDDEN);
  }
}

export const getAttachmentUploadUrlSchema = z.object({
  fileName: z.string().trim().min(1).max(255),
  contentType: z.enum(['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'image/jpeg', 'image/png']),
  token: z.string().trim().min(1, 'Invitation token is required'),
});
